(()=>{const zh=document.documentElement.lang.startsWith('zh');const ids=['fraction','width','shift'];let state={};const defaults={fraction:.1,width:.3,shift:0};const get=k=>document.getElementById('C02-'+k);const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));function update(){const f=+get('fraction').value,w=+get('width').value,d=+get('shift').value;ids.forEach(k=>get(k+'-value').textContent=(+get(k).value).toFixed(2));const mn=(1-f)*10000+f*100000,mw=((1-f)*1e8+f*1e10)/mn,lm=f*1e5/mn,q=Math.exp(.5*(Math.log(10)*.25*w)**2),c=10**(-.25*d);state={fraction:f,width:w,shift:d,true_Mn:mn,true_Mw:mw,apparent_Mn:mn*c/q,apparent_Mw:mw*c*q,long_mass_fraction:lm};get('result').textContent=(zh?'真实 Mn / Mw：':'Actual Mn / Mw: ')+mn.toFixed(0)+' / '+mw.toFixed(0)+' g/mol; '+(zh?'表观：':'apparent: ')+state.apparent_Mn.toFixed(0)+' / '+state.apparent_Mw.toFixed(0)+' g/mol; '+(zh?'长链质量比例：':'long-chain mass: ')+(100*lm).toFixed(1)+'%';const gg=(v,m)=>Math.exp(-.5*((v-m)/w)**2)/(w*Math.sqrt(2*Math.PI));const pts=Array.from({length:2001},(_,i)=>2+18*i/2000);const ys=pts.map(v=>lm*gg(v,8+d)+(1-lm)*gg(v,12+d));const ymax=Math.max(...ys)*1.12;const x=v=>70+(v-2)/18*650,y=s=>285-s/ymax*240;const path=ys.map((s,i)=>(i?'L':'M')+x(pts[i]).toFixed(2)+','+y(s).toFixed(2)).join(' ');let out='<rect width="760" height="350" fill="#fcfbf7"/><path d="M70 40V285H725" fill="none" stroke="#61758a"/><path d="'+path+'" fill="none" stroke="#167d9a" stroke-width="2.5"/>';for(let v=2;v<=20;v+=3)out+='<text x="'+x(v)+'" y="308" text-anchor="middle" font-size="12">'+v+'</text>';for(let j=0;j<=4;j++){let a=ymax*j/4;out+='<text x="61" y="'+(y(a)+4)+'" text-anchor="end" font-size="12">'+a.toFixed(2)+'</text>';}out+='<text x="400" y="337" text-anchor="middle" font-size="14">'+(zh?'洗脱体积 / mL':'Elution volume / mL')+'</text><text x="78" y="25" font-size="13">'+(zh?'归一化质量信号 / mL⁻¹':'Normalized mass signal / mL⁻¹')+'</text>';get('plot').innerHTML=out;}function set(p){for(const k of ids)if(p[k]!==undefined){const el=get(k);el.value=clamp(+p[k],+el.min,+el.max);}update();}ids.forEach(k=>get(k).addEventListener('input',update));get('reset').addEventListener('click',()=>set(defaults));window.CourseLab={set,state:()=>({...state}),reset:()=>set(defaults)};update();})();
